    "causal_conv1d_update": "def causal_conv1d_update(\n    x: torch.Tensor,\n    conv_state: torch.Tensor,\n    weight: torch.Tensor,\n    bias: Optional[torch.Tensor] = None,\n    activation: Union[bool, str, None] = None,\n    cache_seqlens: Optional[torch.Tensor] = None,\n    conv_state_indices: Optional[torch.Tensor] = None,\n    pad_slot_id: int = PAD_SLOT_ID,\n    metadata=None,\n    validate_data=False,\n):\n    if activation is True:\n        activation = \"silu\"\n    if activation not in [None, \"silu\", \"swish\", False]:\n        raise NotImplementedError(\"activation must be None, silu, or swish\")\n    activation = None if activation is False else activation\n\n    unsqueeze = x.dim() == 2\n    if unsqueeze:\n        x = x.unsqueeze(-1)\n    if x.dim() != 3:\n        raise ValueError(f\"x must have shape (batch, dim) or (batch, dim, seqlen), got {tuple(x.shape)}\")\n\n    dtype_in = x.dtype\n    batch, dim, seqlen = x.shape\n    if weight.dim() != 2 or weight.shape[0] != dim:\n        raise ValueError(f\"weight must have shape ({dim}, width), got {tuple(weight.shape)}\")\n    width = weight.shape[1]\n    state_len = conv_state.shape[-1]\n\n    if bias is not None and bias.shape != (dim,):\n        raise ValueError(f\"bias must have shape ({dim},), got {tuple(bias.shape)}\")\n\n    if conv_state_indices is not None:\n        if conv_state_indices.shape[0] != batch:\n            raise ValueError(\"conv_state_indices must have one entry per batch element\")\n        if conv_state.dim() != 3 or conv_state.shape[1] != dim:\n            raise ValueError(\"conv_state must have shape (num_cache_lines, dim, state_len) when conv_state_indices is provided\")\n        valid_mask = conv_state_indices != pad_slot_id\n        out = torch.zeros((batch, dim, seqlen), device=x.device, dtype=dtype_in)\n        if valid_mask.any():\n            gathered_state = conv_state.index_select(0, conv_state_indices[valid_mask].to(torch.long))\n            gathered_x = x[valid_mas